//! 🧪️ Fixed indexed native reads agree with the prepared schema rows and refuse incomplete publications.
use super::*;
use std::cell::Cell;
struct Source<'a>{bytes:&'a[u8],complete:bool,reads:&'a Cell<usize>}
impl EnergyResultSource for Source<'_>{fn complete(&self)->bool{self.complete}fn byte_len(&self)->usize{self.bytes.len()}fn read_fixed<const N:usize>(&self,offset:usize)->Option<[u8;N]>{if N>64{return None;}self.reads.set(self.reads.get()+1);self.bytes.get(offset..offset.checked_add(N)?)?.try_into().ok()}}
#[test]
fn energy_indexed_native_reads_use_prepared_original_partitions_and_locales(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut bytes=[0u8;172];bytes[..4].copy_from_slice(law["magic"].as_str().unwrap().as_bytes());for(index,count)in law["counts"].as_array().unwrap().iter().enumerate(){bytes[4+index*4..8+index*4].copy_from_slice(&(count.as_u64().unwrap()as u32).to_le_bytes());}for(field,bound)in law["bounds"].as_array().unwrap().iter().enumerate(){for index in 0..2{bytes[12+field*16+index*8..20+field*16+index*8].copy_from_slice(&bound[index].as_f64().unwrap().to_le_bytes());}}let rows=law["rows"].as_array().unwrap();for(index,row)in rows.iter().enumerate(){bytes[76+index*24..80+index*24].copy_from_slice(&(row["id"].as_u64().unwrap()as u32).to_le_bytes());for field in 0..4{bytes[80+index*24+field*4..84+index*24+field*4].copy_from_slice(&(row["values"][field].as_f64().unwrap()as f32).to_le_bytes());bytes[96+index*24+field]=row["bands"][field].as_u64().unwrap()as u8;}}let reads=Cell::new(0);let original=bytes.as_ptr();assert!(IndexedEnergyResults::new(Source{bytes:&bytes,complete:false,reads:&reads}).is_none());assert_eq!(reads.get(),0);let result=IndexedEnergyResults::new(Source{bytes:&bytes,complete:true,reads:&reads}).unwrap();assert_eq!(reads.get(),5);for _ in 0..law["repaints"].as_u64().unwrap(){for row in rows{let id=row["id"].as_u64().unwrap()as u32;for field in ResultField::ALL{let band=row["bands"][column(field)].as_u64().unwrap()as usize;assert_eq!(result.color(id,field),SURFACE_ENERGY_BANDS.get(band).map(|color|hex_to_rgb01(color)));}}assert!(result.color(law["missingId"].as_u64().unwrap()as u32,ResultField::ConductionLoss).is_none());}assert_eq!(bytes.as_ptr(),original);assert!(reads.get()<6000);assert_eq!(result.caption(ResultField::ConductionLoss,Locale::En),law["captions"]["en"].as_str().unwrap());assert_eq!(result.caption(ResultField::ConductionLoss,Locale::De),law["captions"]["de"].as_str().unwrap());assert_eq!(IndexedEnergyResults::<Source<'_>>::scale_label(Locale::De),"Ergebnisskala, niedrig bis hoch");eprintln!("[DEBUG] Energy original prepared native ESF2 indexed reads={} 40repaints originalPointer explicitENDE noMapOrSort",reads.get());
}
